const __pageData = JSON.parse('{"title":"Hezbollah","description":"","frontmatter":{"title":"Hezbollah","created":"2026-08-06T00:00:00.000Z","updated":"2026-08-06T00:00:00.000Z","type":"entity","tags":["lebanon","israel","militant-groups","middle-east"],"sources":["raw/badlands-brief-07c.md","raw/badlands-brief-143.md","raw/badlands-brief-0fb.md","raw/badlands-brief-1ae.md","raw/badlands-brief-2c0.md","raw/badlands-brief-625.md","raw/badlands-brief-6a1.md","raw/badlands-brief-6b4.md","raw/badlands-brief-708.md","raw/badlands-brief-8c2.md","raw/badlands-brief-774.md","raw/badlands-brief-9ac.md","raw/badlands-brief-9ea.md","raw/badlands-brief-bb1.md","raw/badlands-brief-c7b.md","raw/badlands-news-brief-048.md","raw/badlands-news-brief-023.md","raw/badlands-news-brief-02f.md","raw/badlands-news-brief-0ad.md","raw/badlands-news-brief-10a.md","raw/badlands-news-brief-099.md","raw/badlands-news-brief-116.md","raw/badlands-news-brief-13f.md","raw/badlands-news-brief-1c3.md","raw/badlands-news-brief-264.md","raw/badlands-news-brief-28e.md","raw/badlands-news-brief-2a0.md","raw/badlands-news-brief-2ad.md","raw/badlands-news-brief-2f2.md","raw/badlands-news-brief-421.md","raw/badlands-news-brief-447.md","raw/badlands-news-brief-6c4.md","raw/badlands-news-brief-69b.md","raw/badlands-news-brief-70a.md","raw/badlands-news-brief-683.md","raw/badlands-news-brief-67e.md","raw/badlands-news-brief-656.md","raw/badlands-news-brief-845.md"],"confidence":"low"},"headers":[],"relativePath":"entities/hezbollah.md","filePath":"entities/hezbollah.md","lastUpdated":null}');
